import { useState, useEffect } from "react";

function Tong() {
  const [a, setA] = useState(2);
  const [tong, setTong] = useState(0);
  useEffect(() => {
    setTong(a * 10);
  }, [a]);
  return (
    <div>
      <p>Tong: {tong}</p>
      <button onClick={() => setA(a + 1)}>Tang a</button>
    </div>
  );
}

export default Tong;
